spec.rawSql:
SELECT SUM(total_kwh_consumed) AS "kWh"
FROM public.batch_cost
WHERE $__timeFilter(calculated_at);

SELECT SUM(total_energy_cost) AS "Custo"
FROM public.batch_cost
WHERE $__timeFilter(calculated_at);

SELECT AVG(energy_cost_per_piece) AS "€/peça"
FROM public.batch_cost
WHERE $__timeFilter(calculated_at);

SELECT ROUND((100.0 * COUNT(*) FILTER (WHERE firing_anomaly) / NULLIF(COUNT(*),0))::numeric, 1) AS "% com anomalia"
FROM public.kiln_firing
WHERE $__timeFilter(created_at);

SELECT COUNT(*) FILTER (WHERE temp_anomaly) AS "Anomalias de temperatura"
FROM public.kiln_firing
WHERE $__timeFilter(created_at);

SELECT COUNT(*) FILTER (WHERE rate_anomaly) AS "Anomalias de taxa"
FROM public.kiln_firing
WHERE $__timeFilter(created_at);
